def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find full separator rows and columns.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] != 0 for r in range(h))]
    sep_color = grid[sep_rows[0]][0] if sep_rows else (grid[0][sep_cols[0]] if sep_cols else 0)

    row_starts = []
    r = 0
    for sr in sep_rows + [h]:
        if r < sr:
            row_starts.append((r, sr))
        r = sr + 1

    col_starts = []
    c = 0
    for sc in sep_cols + [w]:
        if c < sc:
            col_starts.append((c, sc))
        c = sc + 1

    out = [[0] * w for _ in range(h)]
    for r in sep_rows:
        for c in range(w):
            out[r][c] = sep_color
    for c in sep_cols:
        for r in range(h):
            out[r][c] = sep_color

    # Use the nonempty tile outside the first column as the repeating pattern.
    pattern = None
    for r0, r1 in row_starts:
        for c0, c1 in col_starts[1:]:
            cells = [(r - r0, c - c0)
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] not in (0, sep_color)]
            if cells:
                pattern = cells
                break
        if pattern is not None:
            break

    if pattern is None:
        return out

    for r0, r1 in row_starts:
        color = next((grid[r][c] for r in range(r0, r1)
                      for c in range(col_starts[0][0], col_starts[0][1])
                      if grid[r][c] not in (0, sep_color)), 0)
